jQuery(document).ready(function($){$(document).on('click','#header #header_top .row #header_top_right .mobile_button.bookmarks:not(.active)',function(){$(this).addClass('active');$('#header #header_bottom').addClass('active');$('#header #header_top .row #header_top_right .mobile_button.search').removeClass('active');$('#header #header_top_middle').removeClass('active');});$(document).on('click','#header #header_top .row #header_top_right .mobile_button.bookmarks.active',function(){$(this).removeClass('active');$('#header #header_bottom').removeClass('active');});$(document).on('click','#header #header_top .row #header_top_right .mobile_button.search:not(.active)',function(){$(this).addClass('active');$('#header #header_top_middle').addClass('active');$('#header #header_top .row #header_top_right .mobile_button.bookmarks').removeClass('active');$('#header #header_bottom').removeClass('active');});$(document).on('click','#header #header_top .row #header_top_right .mobile_button.search.active',function(){$(this).removeClass('active');$('#header #header_top_middle').removeClass('active');});});;
